Account account = new Account(Name = 'Acme');
List<FormulaRecalcResult> results = Formula.recalculateFormulas(new List<SObject>{account});
System.assertEquals(1, results.size());
System.assert(!results[0].isSuccess());
System.assertEquals(1, results[0].getErrors().size());
FormulaRecalcFieldError err = results[0].getErrors()[0];
System.assertEquals('Unsupported__c', err.getFieldName());
System.assertNotEquals(null, err.getFieldError());

